    lecture_examples = sum(len(l["deep"]["examples"]) for l in data["lectures"])
    lecture_essay_words = sum(sum(len(re.findall(r"[A-Za-z0-9']+", p)) for p in l["deep"]["essay"]) for l in data["lectures"])
    lecture_first_principles_essay_words = sum(sum(len(re.findall(r"[A-Za-z0-9']+", l["deep"]["first_principles_essay"][field])) for field in ["ordinary_problem", "object_on_page", "allowed_change", "protected_fact", "topology_payoff", "outside_use", "wrong_use"]) for l in data["lectures"])
